window.ScripturaLexicons.BDAG_PART_0015 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-airo-bdag\" data-source=\"BDAG\" data-search=\"αἴρω airo levantar tomar carregar remover tirar destruir suspenso levantar âncora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴρω</td><td>Verbo</td><td>levantar; carregar; remover; tirar; partir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aisthanomai-bdag\" data-source=\"BDAG\" data-search=\"αἰσθάνομαι aisthanomai perceber notar compreender discernir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσθάνομαι</td><td>Verbo</td><td>perceber; notar; compreender</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aisthesis-bdag\" data-source=\"BDAG\" data-search=\"αἴσθησις aisthesis percepção sensação discernimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴσθησις</td><td>Substantivo</td><td>percepção; sensação; discernimento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aisthterion-bdag\" data-source=\"BDAG\" data-search=\"αἰσθητήριον aistheterion órgão sentido faculdade discernimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσθητήριον</td><td>Substantivo</td><td>órgão dos sentidos; faculdade de discernimento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischrokerdes-bdag\" data-source=\"BDAG\" data-search=\"αἰσχροκερδής aischrokerdes avarento ganância desonesta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχροκερδής</td><td>Adjetivo</td><td>ávido por ganho desonesto; avarento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischrokerdos-bdag\" data-source=\"BDAG\" data-search=\"αἰσχροκερδῶς aischrokerdos gananciosamente ganho desonesto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχροκερδῶς</td><td>Advérbio</td><td>gananciosamente; por ganho desonesto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischrologia-bdag\" data-source=\"BDAG\" data-search=\"αἰσχρολογία aischrologia fala obscena conversa suja linguagem injuriosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχρολογία</td><td>Substantivo</td><td>fala obscena; conversa suja</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischrologos-bdag\" data-source=\"BDAG\" data-search=\"αἰσχρολόγος aischrologos boca suja linguagem obscena BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχρολόγος</td><td>Substantivo</td><td>pessoa de linguagem obscena</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischros-bdag\" data-source=\"BDAG\" data-search=\"αἰσχρός aischros vergonhoso vil desonroso inaceitável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχρός</td><td>Adjetivo</td><td>vergonhoso; vil</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischrotes-bdag\" data-source=\"BDAG\" data-search=\"αἰσχρότης aischrotes vergonhosidade obscenidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχρότης</td><td>Substantivo</td><td>vergonhosidade; obscenidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischyne-bdag\" data-source=\"BDAG\" data-search=\"αἰσχύνη aischyne vergonha modéstia desonra ato vergonhoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχύνη</td><td>Substantivo</td><td>vergonha; modéstia; desonra</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischynteros-bdag\" data-source=\"BDAG\" data-search=\"αἰσχυντηρός aischynteros modesto decente recatado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχυντηρός</td><td>Adjetivo</td><td>modesto; atento ao decoro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aischyno-bdag\" data-source=\"BDAG\" data-search=\"αἰσχύνω aischyno envergonhar sentir vergonha ser envergonhado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰσχύνω</td><td>Verbo</td><td>envergonhar-se; ser envergonhado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aiteo-bdag\" data-source=\"BDAG\" data-search=\"αἰτέω aiteo pedir solicitar exigir requerer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰτέω</td><td>Verbo</td><td>pedir; solicitar; exigir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aitema-bdag\" data-source=\"BDAG\" data-search=\"αἴτημα aitema pedido solicitação petição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴτημα</td><td>Substantivo</td><td>pedido; solicitação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aitesis-bdag\" data-source=\"BDAG\" data-search=\"αἴτησις aitesis pedido solicitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἴτησις</td><td>Substantivo</td><td>pedido; solicitação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aitia-bdag\" data-source=\"BDAG\" data-search=\"αἰτία aitia causa razão caso circunstância acusação fundamento legal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰτία</td><td>Substantivo</td><td>causa; razão; caso; acusação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aitiama-bdag\" data-source=\"BDAG\" data-search=\"αἰτίαμα aitiama acusação queixa remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">αἰτίαμα</td><td>Substantivo</td><td>ver αἰτίωμα</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-airo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴρω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aírō⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. ἀρῶ; 1 aor. ᾖρα (ἦρα v.l.); pf. ἦρκα · pass. fut. ἀρθήσομαι; 1 aor. ἤρθην; pf. ἦρμαι</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero+; Hermas, como alguns escritores posteriores, também tem <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀείρω\" data-meanings=\"levantar\">ἀείρω</span>.)\n<span class=\"sense-number\">1.</span> <strong>Erguer para lugar ou posição mais alta, levantar, apanhar.</strong> <strong>a.</strong> Literalmente, de pedras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.59\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.59</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18.21</a>; Hs 9, 4, 7; de peixe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.27</a>; caixão, 1 Cl 25:3; mão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 10.5</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.32.40\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 32.40</a>); mãos em oração, 1 Cl 29:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. τὴν χεῖρα ἀπό τινος\" data-meanings=\"retirar a mão de alguém\">αἴ. τὴν χεῖρα ἀπό τινος</span> = renunciar ou afastar-se de alguém, B 19:5; D 4:9. De serpentes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.18</a>; de leito/maca, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.9</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">11 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.8–12</a>; de barco içado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.17</a>; de espírito que carrega pessoa, Hv 2, 1, 1; de cadáver, AcPt Ox 849 verso, 8; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. σύσσημον\" data-meanings=\"levantar um estandarte\">αἴ. σύσσημον</span> ISm 1:2 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Is 5.26</a>). Passivo: 2 Cl 7:4; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄρθητι\" data-meanings=\"ergue-te\">ἄρθητι</span> de montanhas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11.23</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἤρθη νεκρός\" data-meanings=\"foi levantado morto\">ἤρθη νεκρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.9</a>. <strong>b.</strong> Figuradamente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. τοὺς ὀφθαλμοὺς ἄνω\" data-meanings=\"levantar os olhos para cima\">αἴ. τοὺς ὀφθαλμοὺς ἄνω</span> = olhar para cima em oração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.41</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. φωνήν\" data-meanings=\"levantar a voz\">αἴ. φωνήν</span> = clamar em alta voz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρός τινα\" data-meanings=\"a alguém\">πρός τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.24</a>.\n<span class=\"sense-number\">2.</span> <strong>Levantar e mover de um lugar para outro.</strong> <strong>a.</strong> <strong>Tomar/carregar consigo</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σταυρόν\" data-meanings=\"cruz\">σταυρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.32\" target=\"_blank\" rel=\"noopener noreferrer\">27.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">15.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.23</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ζυγόν\" data-meanings=\"jugo\">ζυγόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.29</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινὰ ἐπὶ χειρῶν\" data-meanings=\"alguém sobre as mãos\">τινὰ ἐπὶ χειρῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.11</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.90.12\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 90.12</a>). Passivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.3</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. τι εἰς ὁδόν\" data-meanings=\"levar algo para a viagem\">αἴ. τι εἰς ὁδόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.3</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">22.36</a>. De ganhos de jogador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.24</a>. Figuradamente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δόξαν ἐφ’ ἑαυτὸν αἴ.\" data-meanings=\"tomar glória para si\">δόξαν ἐφ’ ἑαυτὸν αἴ.</span> B 19:3. <strong>b.</strong> <strong>Levar embora, remover.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ταῦτα ἐντεῦθεν\" data-meanings=\"estas coisas daqui\">ταῦτα ἐντεῦθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2.16</a>; corpo de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">19.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">20.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>; de João Batista, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.29</a>; pedra de sepultura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.39</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.41\" target=\"_blank\" rel=\"noopener noreferrer\">41</a>; passivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">20.1</a>; sobras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">15.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.8</a>; fragmentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">6.43</a>; cestos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">8.19 s.</a>; cinturão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.11</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ σόν\" data-meanings=\"o que é teu\">τὸ σόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.14</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. τι ἐκ τῆς οἰκίας\" data-meanings=\"tirar algo da casa\">αἴ. τι ἐκ τῆς οἰκίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.31</a>; tirar alguém do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.15</a>.\n<span class=\"sense-number\">3.</span> <strong>Tirar, remover ou assumir controle, sem sugestão de levantar.</strong> À força, até por matar: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἆρον, ἆρον\" data-meanings=\"fora, fora [com ele]!\">ἆρον, ἆρον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.15</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶρε τοῦτον\" data-meanings=\"tira este\">αἶρε τοῦτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">22.22</a>; AcPl Ha 4, 35 s.; MPol 3:2; 9:2; “varrer”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.39</a>; tirar roupa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.29</a>; armas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.22</a>; talento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.28</a>; chave do conhecimento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.52</a>. Passivo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">19.26</a>. <strong>Conquistar, tomar posse</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.48</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. τὴν ψυχὴν ἀπό τινος\" data-meanings=\"tirar a vida de alguém\">αἴ. τὴν ψυχὴν ἀπό τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.18</a>; “ser tirado da terra”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.33</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.53.8\" target=\"_blank\" rel=\"noopener noreferrer\">Is 53.8</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀφ’ ὑμῶν ἡ βασιλεία\" data-meanings=\"o reino será tirado de vós\">ἀφ’ ὑμῶν ἡ βασιλεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.43</a>; de Satanás tirando a palavra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.12</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν χαρὰν ὑμῶν οὐδεὶς αἴρει ἀφ’ ὑμῶν\" data-meanings=\"ninguém tirará de vós a vossa alegria\">τὴν χαρὰν ὑμῶν οὐδεὶς αἴρει ἀφ’ ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16.22</a>; remover hipocrisia e dúvidas, B 21:4; Hm 9:1; 10, 1, 1; 10, 2, 5; 12, 1, 1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. ἐκ (τοῦ) μέσου\" data-meanings=\"tirar do meio\">αἴ. ἐκ (τοῦ) μέσου</span> = remover/expulsar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 5.2</a>; destruir documento de dívida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2.14</a>; remover ramos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 15.2</a>; remover/apagar pecado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.29</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.36\" target=\"_blank\" rel=\"noopener noreferrer\">36</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3.5</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.53.12\" target=\"_blank\" rel=\"noopener noreferrer\">Is 53.12</a> Aq.); passivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.31</a>; figuradamente, “tomar” para fazer algo do objeto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.15</a>.\n<span class=\"sense-number\">4.</span> <strong>Retirar em sentido comercial</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴρεις ὃ οὐκ ἔθηκας\" data-meanings=\"retiras o que não depositaste\">αἴρεις ὃ οὐκ ἔθηκας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.21 s.</a>.\n<span class=\"sense-number\">5.</span> <strong>Manter alguém em suspenso/incerteza</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴ. τὴν ψυχήν τινος\" data-meanings=\"manter a alma de alguém suspensa\">αἴ. τὴν ψυχήν τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.24</a>.\n<span class=\"sense-number\">6.</span> <strong>Levantar âncora, partir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.13</a>. — Rydbeck 155 s.; B. 669 s. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀείρω\" data-meanings=\"levantar\">ἀείρω</span>. M-M. TW.</p></section></article><article id=\"entry-aisthanomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθάνομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aisthánomai⟧</span><span class=\"separator\">·</span><span class=\"greek\">fut. αἰσθήσῃ / αἰσθηθήσεσθε / αἰσθανθήσεται; 2 aor. ᾐσθόμην; subj. αἴσθωμαι</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ésquilo+.) <span class=\"sense-number\">1.</span> <strong>Ter consciência de algo por meio dos sentidos, notar</strong> (Cleanthes [veja 2, fim]; Appian, <em>Liby.</em> 120 §568; TestJud 15:1; Tat. 17, 4), Dg 2:8 (compare EpJer 19; 23). <span class=\"sense-number\">2.</span> <strong>Ter capacidade de discernir e, portanto, compreender o que não é prontamente compreensível, compreender</strong> (X., <em>Cyr.</em> 1, 5, 4 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 17.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">24.14</a>; Ar.; Iren. 1, 4, 1 [Harv. I 32, 7]): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥῆμα\" data-meanings=\"palavra; declaração\">ῥῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.45</a> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοέω\" data-meanings=\"ignorar\">ἀγνοέω</span>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γνώμην\" data-meanings=\"pensamento; intenção\">γνώμην</span> B 2:9; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"que\">ὅτι</span> seguinte, B 6:18; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσθάνεσθε\" data-meanings=\"percebeis/notais\">αἰσθάνεσθε</span> com interrogativa indireta, B 11:8; compare 13:3. Ambos os sentidos aparecem no jogo de palavras de Cleanthes: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ αἰσθάνομαι, ὅτι αἰσθάνῃ;\" data-meanings=\"não percebo que compreendes?\">οὐκ αἰσθάνομαι, ὅτι αἰσθάνῃ;</span>. — B. 1020. DELG s.v. 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀΐω\" data-meanings=\"perceber; ouvir\">ἀΐω</span>. M-M. TW. Sv.</p></section></article><article id=\"entry-aisthesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴσθησις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aísthēsis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Pré-socráticos, Eurípides e outros; Epict., Herm. Wr.; LXX, especialmente Provérbios; Fílon; Jos., <em>Bell.</em> 7, 69; <em>C. Ap.</em> 2, 178; Test12Patr; SibOr Fgm. 3, 23; Just.; Mel., Fgm. 2; Ath., <em>R.</em> 56, 17 e outros.) <span class=\"sense-number\">1.</span> <strong>Capacidade de ser afetado por estímulos externos, percepção, sensação</strong> (EpArist 213), Dg 2:9, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λογισμός\" data-meanings=\"raciocínio\">λογισμός</span>. <span class=\"sense-number\">2.</span> <strong>Capacidade de compreender, discernimento</strong> (compare Iren. 1, 15, 2 [Harv. I 149, 3]), denotando compreensão moral (compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσθητήριον\" data-meanings=\"faculdade de discernimento\">αἰσθητήριον</span> e A. Bonhöffer, <em>Epikt. u. d. NT</em> 1911, 105), ao lado de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπίγνωσις\" data-meanings=\"conhecimento; percepção\">ἐπίγνωσις</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περισσεύειν ἐν … πάσῃ αἰσθήσει εἰς τὸ …\" data-meanings=\"transbordar em … todo discernimento, para que …\">περισσεύειν ἐν … πάσῃ αἰσθήσει εἰς τὸ …</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.9</a>. — B. 1020. DELG s.v. 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀΐω\" data-meanings=\"perceber; ouvir\">ἀΐω</span>. M-M. TW. Sv.</p></section></article><article id=\"entry-aisthterion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσθητήριον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aisthētḗrion⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Hipócrates e outros; Herm. Wr. 7, 3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 4.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 2.22</a>; Fílon.) Literalmente, <strong>órgão do sentido</strong>; figuradamente, <strong>capacidade de discernimento, faculdade</strong>, da capacidade de tomar decisões morais (P. Linde, <em>De Epicuri Vocab.</em>, Bresl. Philol. Abh. X/3, 1906, 32): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ αἰσθητήρια γεγυμνασμένα ἔχειν πρὸς διάκρισιν καλοῦ τε και κακοῦ\" data-meanings=\"ter as faculdades exercitadas para distinguir entre o bem e o mal\">τὰ αἰσθητήρια γεγυμνασμένα ἔχειν πρὸς διάκρισιν καλοῦ τε και κακοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5.14</a> (compare Galeno, <em>De Dign. Puls.</em> 3, 2, vol. VIII 892 K.; Iren. 4, 38, 2 [Harv. II 294, 12]). — DELG s.v. 1 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀΐω\" data-meanings=\"perceber; ouvir\">ἀΐω</span>. TW.</p></section></article><article id=\"entry-aischrokerdes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχροκερδής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischrokerdḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Desde Eur., <em>And.</em> 451; Hdt. 1, 187; Fílon, <em>Sacr. Abel.</em> 32 fim; TestJud 16:1.) <strong>Desavergonhadamente ávido por dinheiro, avarento, amante de ganho desonesto</strong> (compare Lysias 12, 19), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3.8</a> (v. 3 v.l.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.7</a> (também em catálogo de vícios, Ptolem., <em>Apotel.</em> 3, 14, 15). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶσχος\" data-meanings=\"vergonha; desonra\">αἶσχος</span>. Spicq.</p></section></article><article id=\"entry-aischrokerdos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχροκερδῶς</h1><div class=\"entry-meta\"><span>advérbio</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischrokerdō̂s⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχροκερδής\" data-meanings=\"ávido por ganho desonesto\">αἰσχροκερδής</span>: <strong>por amor ao ganho desonesto, gananciosamente</strong> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"προθύμως\" data-meanings=\"de boa vontade; prontamente\">προθύμως</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 5.2</a>.</p></section></article><article id=\"entry-aischrologia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρολογία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischrología⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Xenofonte e outros; Polyb., Diod S, Plut., Epict.; POxy 410, 77.) <strong>Fala de tipo geralmente considerado de mau gosto, fala obscena, conversa suja.</strong> Aristóteles, <em>EN</em> 4, 8 [1128a], contrasta a preferência pela obscenidade no drama antigo com o gosto mais refinado de épocas posteriores e argumenta que <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρολογία\" data-meanings=\"fala obscena\">αἰσχρολογία</span> pode ser esperada de pessoas de natureza servil, mas não de um homem culto. Clem. Al., <em>Paed.</em> 2, 6, 52 define-a apropriadamente como narrativa a respeito de atos indecorosos, por exemplo falar de adultério ou pederastia; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρός\" data-meanings=\"obsceno; vergonhoso\">αἰσχρός</span> = “obsceno” em Ps.-Demetr., <em>Eloc.</em> 151. Expressões obscenas também podiam dar tom a observações depreciativas; por isso, “linguagem injuriosa/escabrosa” é pertinente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.8</a>, especialmente porque <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βλασφημία\" data-meanings=\"difamação; blasfêmia\">βλασφημία</span> a precede imediatamente. O sentido geral “conversa suja” convém a D 5:1, que pode abranger tanto histórias obscenas quanto fala injuriosa. — A. Wikenhauser, BZ 8, 1910, 270. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶσχος\" data-meanings=\"vergonha; desonra\">αἶσχος</span>. M-M. Sv.\n</p></section></article><article id=\"entry-aischrologos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρολόγος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischrológos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Pollux 6, 123; 8, 80 s.) <strong>Pessoa de linguagem obscena, pessoa de boca suja</strong> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρολογία\" data-meanings=\"fala obscena; conversa suja\">αἰσχρολογία</span>), D 3:3. — M-M. s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρολογία\" data-meanings=\"fala obscena\">αἰσχρολογία</span>.\n</p></section></article><article id=\"entry-aischros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρός</h1><div class=\"entry-meta\"><span class=\"greek\">ά, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischrós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Em vários sentidos, desde “feio” exteriormente até “vil” como deformidade moral, Homero+; também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρότερα\" data-meanings=\"coisas mais vergonhosas\">αἰσχρότερα</span> Ar. 11, 7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴσχιστον\" data-meanings=\"o mais vergonhoso\">αἴσχιστον</span> Just., <em>A</em> II, 7, 3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρῶς\" data-meanings=\"vergonhosamente\">αἰσχρῶς</span> Just., <em>A</em> I, 27, 1; <em>D.</em> 90, 1.) Termo especialmente significativo numa sociedade orientada por honra e vergonha; em geral, refere-se ao que deixa de corresponder aos padrões morais e culturais esperados, oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καλός\" data-meanings=\"belo; nobre; bom\">καλός</span>: <strong>social ou moralmente inaceitável, vergonhoso, vil</strong>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρόν κέρδος\" data-meanings=\"ganho vergonhoso/desonesto\">αἰσχρόν κέρδος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.11</a> (Theognis 466; Polyb. 6, 46, 3; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχροκερδής\" data-meanings=\"ávido por ganho desonesto\">αἰσχροκερδής</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχροκερδῶς\" data-meanings=\"gananciosamente\">αἰσχροκερδῶς</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥῆμα\" data-meanings=\"palavra; expressão\">ῥῆμα</span> Hv 1, 1, 7. Neutro na expressão <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρόν ἐστί τινι\" data-meanings=\"é vergonhoso para alguém\">αἰσχρόν ἐστί τινι</span> com infinitivo seguinte (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 16.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 12.12</a>): para uma mulher cortar o cabelo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11.6</a>; falar numa reunião, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">14.35</a>; sem pessoa expressa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.12</a>. Também o plural <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρά\" data-meanings=\"coisas vergonhosas\">αἰσχρά</span> (subentende-se <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐστιν\" data-meanings=\"são\">ἐστιν</span>), 1 Cl 47:6. — B. 1195. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶσχος\" data-meanings=\"vergonha; desonra\">αἶσχος</span>. M-M. TW. Sv.\n</p></section></article><article id=\"entry-aischrotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχρότης</h1><div class=\"entry-meta\"><span class=\"greek\">ητος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischrótēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Gama de sentidos como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρός\" data-meanings=\"vergonhoso; vil\">αἰσχρός</span>: Pla., <em>Gorg.</em> 525a; Artem. 4, 2 p. 204, 8.) <strong>Comportamento que afronta padrões sociais e morais, vergonhosidade, obscenidade</strong>; abstrato pelo concreto = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχρολογία\" data-meanings=\"fala obscena\">αἰσχρολογία</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.4</a> (K. Kuhn, NTS 7, 1961, 339 [Qumran]). — TW.\n</p></section></article><article id=\"entry-aischyne-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχύνη</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischúnē⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Theognis, Ésquilo e outros; papiros, LXX; En 13:5; PsSol 9:6; TestLevi 15:2; Ar. 13:5; Just., <em>A</em> I, 16, 3; Ath. 1, 4; Mel., <em>P.</em> 68, 483.)\n<span class=\"sense-number\">1.</span> <strong>Sensibilidade diante da possibilidade de desonra, modéstia, vergonha</strong>, sentimento que alguém possui (Aristoxenus, Fgm. 42a; Diod S 2, 4, 3; Plut., <em>Mor.</em> 248b; UPZ 70, 25 [séc. II a.C.]; PGM 17a, 8; PsSol 9:6; En 13:5; Jos., <em>Ant.</em> 5, 147). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ τῆς αἰσχύνης ἔνδυμα πατεῖν\" data-meanings=\"pisar a veste da vergonha\">τὸ τῆς αἰσχύνης ἔνδυμα πατεῖν</span> provavelmente “despir e pisar sob os pés a veste da vergonha” — usada pelas pessoas desde o despertar da modéstia, isto é, a queda (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 3.7</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">2.25</a>) —, GEg 252, 57. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ κρυπτὰ τῆς αἰ.\" data-meanings=\"as coisas ocultas da vergonha\">τὰ κρυπτὰ τῆς αἰ.</span> = aquilo que alguém oculta por sentimento de vergonha, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 4.2</a>. <strong>Modéstia, reverência</strong>, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φόβος\" data-meanings=\"temor; respeito\">φόβος</span>, de escravos para com senhores, D 4:11; B 19:7.\n<span class=\"sense-number\">2.</span> <strong>Experiência de ignomínia que sobrevém a alguém, vergonha, desonra</strong> (Ath. 1, 4; Diod S 2, 23, 2; Appian, <em>Samn.</em> 4 §11; PEleph 1, 6; PTebt 104, 30; POxy 471, 78; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.25.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 25.22</a>; EpArist 206; Fílon; TestLevi 15:2): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ αἰ. τῆς γυμνότητος\" data-meanings=\"a vergonha da nudez\">ἡ αἰ. τῆς γυμνότητος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καταφρονεῖν αἰσχύνης\" data-meanings=\"desprezar a vergonha\">καταφρονεῖν αἰσχύνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ δόξα ἐν τῇ αἰσχύνῃ αὐτῶν\" data-meanings=\"a glória deles está naquilo que lhes causa vergonha\">ἡ δόξα ἐν τῇ αἰσχύνῃ αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3.19</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετὰ αἰσχύνης\" data-meanings=\"com vergonha; em desonra\">μετὰ αἰσχύνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.9</a>.\n<span class=\"sense-number\">3.</span> <strong>Prática de algo vergonhoso, ato vergonhoso</strong>, plural (Eur., <em>Herc.</em> 1423; Isocr. 14, 50; Aeschin. 1, 154; Jos., <em>Ant.</em> 4, 260): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπαφρίζειν τὰς αἰ.\" data-meanings=\"espumar seus atos vergonhosos\">ἐπαφρίζειν τὰς αἰ.</span> como ondas lançando espuma, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 13</a>. — M. Klopfenstein, <em>Scham u. Schande nach d. AT</em>, 1972. — B. 1141. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶσχος\" data-meanings=\"vergonha; desonra\">αἶσχος</span>. M-M. TW.\n</p></section></article><article id=\"entry-aischynteros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχυντηρός</h1><div class=\"entry-meta\"><span class=\"greek\">ά, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aischuntērós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Platão e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.26.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 26.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.32.10\" target=\"_blank\" rel=\"noopener noreferrer\">32.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.41.27\" target=\"_blank\" rel=\"noopener noreferrer\">41.27</a>.) <strong>Relativo a ter consideração pelo decoro, modesto</strong>, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τρυφερός\" data-meanings=\"delicado\">τρυφερός</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πραΰς\" data-meanings=\"manso\">πραΰς</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡσύχιος\" data-meanings=\"tranquilo\">ἡσύχιος</span>, do anjo justo, Hm 6, 2, 3. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶσχος\" data-meanings=\"vergonha; desonra\">αἶσχος</span>.\n</p></section></article><article id=\"entry-aischyno-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰσχύνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aischúnō⟧</span><span class=\"separator\">·</span><span class=\"greek\">impf. ᾐσχυνόμην; fut. pass. αἰσχυνθήσομαι; 1 aor. pass. ᾐσχύνθην; subj. αἰσχυνθῶ</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Em nossa literatura apenas médio e passivo; Homero+; inscrições, papiros, LXX, Test12Patr; com particípio seguinte Just., <em>D.</em> 123, 4.)\n<span class=\"sense-number\">1.</span> <strong>Ter sentimento de vergonha, envergonhar-se</strong> (SIG 1168, 122; UPZ 62, 27 [161 a.C.]; Fílon, <em>Spec. Leg.</em> 1, 321; Did., <em>Gen.</em> 84, 28). Com infinitivo seguinte: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπαιτεῖν\" data-meanings=\"mendigar\">ἐπαιτεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετ’ αὐτῶν μένειν\" data-meanings=\"permanecer com eles\">μετ’ αὐτῶν μένειν</span> Hs 9, 11, 3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξ αὐτῶν λέγεσθαι\" data-meanings=\"ser chamado um deles\">ἐξ αὐτῶν λέγεσθαι</span> IRo 9:2. Absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.16</a> P72; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">4.16</a>; IEph 11:1 — talvez “ter reverência”. GMary 463, 25–26; Ox 655, 22 s. (ASyn. 67, 35).\n<span class=\"sense-number\">2.</span> <strong>Experimentar vergonha, ser envergonhado, ser desonrado</strong>, isto é, como frequentemente na LXX para “decepcionar-se numa esperança”, oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρρησία\" data-meanings=\"confiança; franqueza\">παρρησία</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 10.8</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπό τινος\" data-meanings=\"diante de alguém\">ἀπό τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 2.28</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἶσχος\" data-meanings=\"vergonha; desonra\">αἶσχος</span>. M-M s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰσχύνομαι\" data-meanings=\"envergonhar-se\">αἰσχύνομαι</span>. TW.\n</p></section></article><article id=\"entry-aiteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aitéō⟧</span><span class=\"separator\">·</span><span class=\"greek\">impv. αἴτει; fut. αἰτήσω; 1 aor. ᾔτησα; pf. ᾔτηκα · méd.: impv. αἰτοῦ; impf. ᾐτούμην; fut. αἰτήσομαι; 1 aor. ᾐτησάμην; impv. αἴτησαι</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+.) <strong>Pedir, pedir por, solicitar, exigir</strong>, com expectativa de receber resposta. Não há distinção real entre ativo e médio em nossa literatura; a distinção dos gramáticos antigos — ativo “pedir diretamente”, médio “pedir como empréstimo” — tem validade muito limitada (B-D-F §316, 2; Mlt. 160 s.; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.2 s.</a>, onde parecem intercambiáveis).\nCom acusativo da pessoa ou coisa pedida: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἰχθύν\" data-meanings=\"peixe\">ἰχθύν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.10</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ σῶμα τοῦ Ἰησοῦ\" data-meanings=\"o corpo de Jesus\">τὸ σῶμα τοῦ Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.52</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πινακίδιον\" data-meanings=\"tabuinha\">πινακίδιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.63</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰρήνην\" data-meanings=\"paz\">εἰρήνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.20</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φῶτα\" data-meanings=\"luzes\">φῶτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.29</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σημεῖα\" data-meanings=\"sinais\">σημεῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν Βαραββᾶν\" data-meanings=\"Barrabás\">τὸν Βαραββᾶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.20</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.6</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βασιλέα\" data-meanings=\"rei\">βασιλέα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.21</a>. Em geral, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί\" data-meanings=\"o quê? algo\">τί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">10.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅ\" data-meanings=\"aquilo que\">ὅ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτῆσαι τὴν κεφαλὴν Ἰωάννου\" data-meanings=\"pedir a cabeça de João\">αἰτῆσαι τὴν κεφαλὴν Ἰωάννου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.24</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πράγματος οὗ ἐὰν αἰτήσωνται\" data-meanings=\"aquilo que pedirem\">πράγματος οὗ ἐὰν αἰτήσωνται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.19</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3.20</a>.\nCom indicação da finalidade: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰ. τὸ σῶμα τοῦ κυρίου πρὸς ταφήν\" data-meanings=\"pedir o corpo do Senhor para sepultamento\">αἰ. τὸ σῶμα τοῦ κυρίου πρὸς ταφήν</span> GPt 2:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινί τι αἰ.\" data-meanings=\"pedir algo em favor de alguém\">τινί τι αἰ.</span> IRo 3:2. Com acusativo da pessoa a quem se pede: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">6.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">7.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">11.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.28</a>. Com duplo acusativo, <strong>pedir algo a alguém</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.22 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">10.35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">15.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">16.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.11</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰ. τινὰ λόγον\" data-meanings=\"exigir de alguém uma prestação de contas\">αἰ. τινὰ λόγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.15</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί ἀπό τινος\" data-meanings=\"algo de alguém\">τί ἀπό τινος</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 5.15</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.20</a> v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί παρά τινος\" data-meanings=\"algo da parte de alguém\">τί παρά τινος</span>: esmola, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.2</a>; absoluto <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴτησαι παρ’ ἐμοῦ\" data-meanings=\"pede-me\">αἴτησαι παρ’ ἐμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.33</a> D; 1 Cl 36:4 (ambos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 2.8</a>); Hs 5, 4, 5; Hm 9:1; 2, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.5</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰ. χάριν\" data-meanings=\"pedir um favor\">αἰ. χάριν</span> B 21:7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτούμενοι χάριν κατ’ αὐτοῦ\" data-meanings=\"pedindo um favor contra ele\">αἰτούμενοι χάριν κατ’ αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτούμενοι κατ’ αὐτοῦ καταδίκην\" data-meanings=\"pedindo sua condenação\">αἰτούμενοι κατ’ αὐτοῦ καταδίκην</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰ. περί τινος\" data-meanings=\"orar por alguém\">αἰ. περί τινος</span> IRo 8:3.\nO modo de pedir pode ser especificado: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κακῶς\" data-meanings=\"mal, de maneira errada\">κακῶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.3</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῇ προσευχῇ\" data-meanings=\"na oração\">ἐν τῇ προσευχῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δεήσεσιν αἰ. τὸν θεόν\" data-meanings=\"suplicar a Deus com súplicas\">δεήσεσιν αἰ. τὸν θεόν</span> Pol 7:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅσα προσεύχεσθε κ. αἰτεῖσθε\" data-meanings=\"tudo quanto orais e pedis\">ὅσα προσεύχεσθε κ. αἰτεῖσθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11.24</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πίστει\" data-meanings=\"com fé\">ἐν πίστει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.6</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῷ ὀνόματί μου\" data-meanings=\"em meu nome\">ἐν τῷ ὀνόματί μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14.13 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">15.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">16.24</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">26</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί κατὰ τὸ θέλημα αὐτοῦ\" data-meanings=\"algo segundo a vontade dele\">τί κατὰ τὸ θέλημα αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 5.14</a>. Elipticamente, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτεῖσθαι καθῶς ἐποίει αὐτοῖς\" data-meanings=\"pedir [que fizesse] como costumava fazer-lhes\">αἰτεῖσθαι καθῶς ἐποίει αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.8</a>.\nCom acusativo e infinitivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αὐτὸν σταυρωθῆναι\" data-meanings=\"que ele fosse crucificado\">αὐτὸν σταυρωθῆναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.23</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.14</a>. Com infinitivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πεῖν αἰτεῖς\" data-meanings=\"pedes para beber\">πεῖν αἰτεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.9</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾐτήσατο εὑρεῖν σκήνωμα\" data-meanings=\"pediu que lhe fosse permitido encontrar morada\">ᾐτήσατο εὑρεῖν σκήνωμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.46</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰ. θεοῦ ἐπιτυχεῖν\" data-meanings=\"pedir alcançar a presença de Deus\">αἰ. θεοῦ ἐπιτυχεῖν</span> ITr 12:2; compare IRo 1:1; negativo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτοῦμαι μὴ ἐγκακεῖν\" data-meanings=\"peço que não desanimeis\">αἰτοῦμαι μὴ ἐγκακεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3.13</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα\" data-meanings=\"para que\">ἵνα</span> seguinte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.9</a>. Absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.7 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.9 s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 5.16</a>; médio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.25</a>. — B. 1270 s. DELG. M-M. TW.\n</p></section></article><article id=\"entry-aitema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴτημα</h1><div class=\"entry-meta\"><span class=\"greek\">τος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aítēma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Platão e outros; POxy 1273, 28 [séc. III d.C.]; LXX; PsSol 6:6; Fílon, <em>Spec. Leg.</em> 1, 43; Jos., <em>Ant.</em> 8, 24; CPJ 153, 52 [41 d.C.].) <strong>Pedido, solicitação</strong>, Hm 9:4. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ αἰ. γνωριζέσθω πρὸς τὸν θεόν\" data-meanings=\"que os vossos pedidos sejam conhecidos diante de Deus\">τὰ αἰ. γνωριζέσθω πρὸς τὸν θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.6</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτεῖσθαι τὸ αἴ.\" data-meanings=\"fazer um pedido\">αἰτεῖσθαι τὸ αἴ.</span> Hm 9:7, 8. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπέκρινεν τὸ αἴτημα γενέσθαι\" data-meanings=\"decidiu que o pedido fosse concedido\">ἐπέκρινεν τὸ αἴτημα γενέσθαι</span>, de Pilatos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.24</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔχειν τὰ αἰ.\" data-meanings=\"obter os pedidos\">ἔχειν τὰ αἰ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 5.15</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λαμβάνεσθαι τὰ αἰ.\" data-meanings=\"receber aquilo que se pede\">λαμβάνεσθαι τὰ αἰ.</span> Hs 4:6; compare Hm 9:5, 7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ αἴ. τῆς ψυχῆς σου πληροφορήσει\" data-meanings=\"[o Senhor] cumprirá a petição de tua alma\">τὸ αἴ. τῆς ψυχῆς σου πληροφορήσει</span> Hm 9:2. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτέω\" data-meanings=\"pedir\">αἰτέω</span>. M-M. TW. Sv.\n</p></section></article><article id=\"entry-aitesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴτησις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aítēsis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Heródoto+; Aristaen., <em>Ep.</em> 2, 7 p. 162; inscrições, papiros, LXX; TestAbr A 9 p. 87, 1 [Stone p. 22] e outros; ApcSed 12; Fílon; Jos., <em>Ant.</em> 10, 27; 17, 232.) <strong>Pedido, solicitação</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πληρῶσαι τὴν αἴτησιν\" data-meanings=\"cumprir o pedido\">πληρῶσαι τὴν αἴτησιν</span> ITr 13:3 (compare TestAbr A 15 p. 96, 3 [Stone p. 40]); compare IPol 7:1 v.l. Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτέω\" data-meanings=\"pedir\">αἰτέω</span>.\n</p></section></article><article id=\"entry-aitia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aitía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴτιος\" data-meanings=\"causa; responsável\">αἴτιος</span>; Píndaro+; inscrições, papiros, LXX; En 21:4; TestSol 11:2 “doença”; GrBar, Fílon, Josefo, Just., Tat., Ath., Mel., <em>P.</em> 56, 411.)\n<span class=\"sense-number\">1.</span> <strong>Aquilo que é responsável por uma condição, causa, razão.</strong> Dg 5:17. Regido por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διά\" data-meanings=\"por causa de\">διά</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διὰ ταύτην τὴν αἰτίαν\" data-meanings=\"por esta razão\">διὰ ταύτην τὴν αἰτίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.20</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">10.21</a>; 1 Cl 44:2; 2 Cl 10:3; Hs 9, 8, 3. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ δι’ ἄλλην τινὰ αἰ. … ἀλλά\" data-meanings=\"por nenhuma outra razão … senão\">οὐ δι’ ἄλλην τινὰ αἰ. … ἀλλά</span> 1 Cl 51:5. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δι’ ἣν αἰτίαν\" data-meanings=\"por qual razão\">δι’ ἣν αἰτίαν</span> em pergunta indireta, “por que”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.24</a>; no início da sentença como conjunção causal, <strong>por esta razão, portanto</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 1.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.11</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατὰ πᾶσαν αἰτίαν\" data-meanings=\"por toda e qualquer causa\">κατὰ πᾶσαν αἰτίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19.3</a>.\n<span class=\"sense-number\">2.</span> <strong>O estado real das coisas, caso, circunstância, relação</strong> — latinismo <em>causa</em>, B-D-F §5, 3b: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ οὕτως ἐστὶν ἡ αἰ. τοῦ ἀνθρώπου μετὰ τῆς γυναικός\" data-meanings=\"se é assim a relação do homem com a mulher\">εἰ οὕτως ἐστὶν ἡ αἰ. τοῦ ἀνθρώπου μετὰ τῆς γυναικός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19.10</a>.\n<span class=\"sense-number\">3.</span> <strong>Base para ação judicial</strong>, termo técnico jurídico.\n<strong>a.</strong> <strong>Acusação, fundamento para queixa.</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.28</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰ. εὑρίσκειν ἔν τινι\" data-meanings=\"encontrar fundamento para acusação em alguém\">αἰ. εὑρίσκειν ἔν τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">19.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.6\" target=\"_blank\" rel=\"noopener noreferrer\">6</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτία θανάτου\" data-meanings=\"causa/fundamento de morte\">αἰτία θανάτου</span> = lat. <em>causa capitalis</em>, fundamento para pena capital, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.18\" target=\"_blank\" rel=\"noopener noreferrer\">28.18</a>. A acusação especificada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.26</a>.\n<strong>b.</strong> <strong>Acusação formal.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτίαν φέρειν\" data-meanings=\"apresentar acusação\">αἰτίαν φέρειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱ κατ’ αὐτοῦ αἰ.\" data-meanings=\"as acusações formais contra ele\">αἱ κατ’ αὐτοῦ αἰ.</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">27</a>. — B. 1183; 1244. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἴτιος\" data-meanings=\"causa; responsável\">αἴτιος</span>. M-M.\n</p></section></article><article id=\"entry-aitiama-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰτίαμα</h1><div class=\"entry-meta\"><span class=\"greek\">τος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aitíama⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\nVeja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἰτίωμα\" data-meanings=\"acusação; queixa\">αἰτίωμα</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.7</a> v.l.\n</p></section></article>"};
